INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > IT-Sicherheit > Datensicherheit > Authentifizierung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Authentifizierung immer notwendig, um den Zugriff auf sensible Daten zu sichern?', 2, '[{"text": "Ja", "correct": true, "because": "Authentifizierung stellt die Identität des Nutzers sicher"}, {"text": "Nein", "correct": false, "because": "Ohne Authentifizierung fehlt die Identitätsprüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Authentifizierung ohne Passwörter erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Biometrie oder Token sind Alternativen"}, {"text": "Nein", "correct": false, "because": "Passwörter sind nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Authentifizierung immer eine Zwei-Faktor-Methode beinhalten?', 2, '[{"text": "Nein", "correct": true, "because": "Ein-Faktor-Authentifizierung ist auch möglich"}, {"text": "Ja", "correct": false, "because": "Zwei-Faktor ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Authentifizierungsmechanismen durch Brute-Force-Angriffe kompromittiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Schwache Passwörter sind anfällig"}, {"text": "Nein", "correct": false, "because": "Risiko besteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Authentifizierung dasselbe wie die Autorisierung?', 2, '[{"text": "Nein", "correct": true, "because": "Authentifizierung prüft Identität, Autorisierung Berechtigungen"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird am häufigsten für die Authentifizierung verwendet?', 2, '[{"text": "Passwort", "correct": true, "because": "Weit verbreitet und einfach"}, {"text": "Fingerabdruck", "correct": false, "because": "Weniger universell"}, {"text": "Smartcard", "correct": false, "because": "Spezifischer Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Authentifizierung primär?', 3, '[{"text": "Überprüfung der Identität", "correct": true, "because": "Stellt sicher, wer zugreift"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Anderes Sicherheitsziel"}, {"text": "Zugriffsberechtigung", "correct": false, "because": "Aufgabe der Autorisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik erhöht die Sicherheit der Authentifizierung am effektivsten?', 2, '[{"text": "Zwei-Faktor-Authentifizierung", "correct": true, "because": "Kombiniert Wissen und Besitz"}, {"text": "Längere Passwörter", "correct": false, "because": "Hilfreich, aber weniger umfassend"}, {"text": "CAPTCHA", "correct": false, "because": "Schützt gegen Bots, nicht direkt Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schwäche haben einfache Passwort-basierte Authentifizierungen?', 2, '[{"text": "Anfälligkeit für Phishing", "correct": true, "because": "Nutzer können getäuscht werden"}, {"text": "Langsame Verarbeitung", "correct": false, "because": "Nicht primäres Problem"}, {"text": "Hohe Kosten", "correct": false, "because": "Kosten sind gering"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird häufig für sichere Authentifizierung in Webanwendungen verwendet?', 2, '[{"text": "OAuth", "correct": true, "because": "Ermöglicht sichere Drittanbieter-Authentifizierung"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung, nicht Authentifizierung"}, {"text": "SMTP", "correct": false, "because": "E-Mail-Protokoll"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methoden können für die Authentifizierung eingesetzt werden?', 4, '[{"text": "Passwörter", "correct": true, "because": "Wissen-basierte Methode"}, {"text": "Biometrie", "correct": true, "because": "Physische Merkmale"}, {"text": "Smartcards", "correct": true, "because": "Besitz-basierte Methode"}, {"text": "Bildschirmfarben", "correct": false, "because": "Keine Authentifizierungsmethode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren erhöhen die Sicherheit der Authentifizierung?', 3, '[{"text": "Mehrfaktor-Authentifizierung", "correct": true, "because": "Kombiniert mehrere Methoden"}, {"text": "Passwort-Komplexität", "correct": true, "because": "Erschwert Brute-Force"}, {"text": "Regelmäßige Passwortänderung", "correct": true, "because": "Reduziert Risiko bei Kompromittierung"}, {"text": "Kürzere Passwörter", "correct": false, "because": "Schwächt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedrohungen gefährden die Authentifizierung?', 4, '[{"text": "Phishing", "correct": true, "because": "Täuscht Nutzer zur Preisgabe"}, {"text": "Brute-Force-Angriffe", "correct": true, "because": "Errät Passwörter"}, {"text": "Keylogger", "correct": true, "because": "Zeichnet Eingaben auf"}, {"text": "Langsame Server", "correct": false, "because": "Kein Sicherheitsrisiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen eine sichere Authentifizierung?', 3, '[{"text": "OAuth", "correct": true, "because": "Sichert Drittanbieter-Zugriff"}, {"text": "SAML", "correct": true, "because": "Single Sign-On-Standard"}, {"text": "TOTP", "correct": true, "because": "Zeitbasierte Einmalpasswörter"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien sollten bei der Authentifizierung beachtet werden?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schutz vor unbefugtem Zugriff"}, {"text": "Benutzerfreundlichkeit", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Skalierbarkeit", "correct": true, "because": "Anpassung an Nutzerzahl"}, {"text": "Maximale Komplexität", "correct": false, "because": "Kontraproduktiv"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Authentifizierung überprüft die Identität eines Nutzers. b) Sie ist dasselbe wie Autorisierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Identität ja, Autorisierung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zwei-Faktor-Authentifizierung erhöht die Sicherheit. b) Passwörter sind unknackbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zwei-Faktor ja, Passwörter knackbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Biometrische Authentifizierung ist passwortfrei möglich. b) Sie ist immer sicherer als Passwörter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Passwortfrei ja, Sicherheit nicht immer höher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Phishing ist eine Bedrohung für die Authentifizierung. b) Zwei-Faktor-Authentifizierung ist Pflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Phishing ja, Zwei-Faktor optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) OAuth unterstützt sichere Authentifizierung. b) Authentifizierung schützt vor Datenverlust.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "OAuth ja, Datenverlust nicht direkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

